components.css:
.ds-theme { display: inline-flex; position: relative; align-items: center; gap: 9px; min-height: 38px; padding: 6px 12px; border: 1px solid var(--ws-rule, #e1e9f5); border-radius: 7px; color: var(--ws-muted, #536382); font-size: 14px; white-space: nowrap; }
.ds-theme { font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; line-height: 1.5; }
.ds-theme select { appearance: none; width: 68px; margin-left: -5px; border: 0; background: transparent; color: var(--ws-ink, #0b1234); font: inherit; cursor: pointer; }
.ds-theme select:disabled { cursor: default; opacity: 1; }
.ds-theme select option { background: var(--ws-panel, #ffffff); color: var(--ws-ink, #0b1234); }
.ds-theme > svg:last-child { pointer-events: none; }
.ds-theme select:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }

.ds-copy { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin: -4px -6px -4px auto; border-radius: 3px; color: var(--ws-muted, #536382); cursor: pointer; }
.ds-copy { border: 0; background: transparent; padding: 0; font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; }
.ds-copy:hover { background: var(--ws-active, #eaf2ff); color: var(--ws-blue, #005de7); }
.ds-copy:disabled { cursor: wait; }
.ds-copy:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }

.ds-explorer { font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; line-height: 1.5; }
.ds-explorer-link { display: flex; align-items: center; gap: 12px; min-height: 32px; padding: 3px 8px; border-radius: 4px; color: var(--ws-muted, #536382); font-size: clamp(12px, 1.05vw, 16px); line-height: 1.35; text-decoration: none; }
.ds-explorer-link:hover { color: var(--ws-blue, #005de7); background: var(--ws-soft, #f5f8fd); }
.ds-explorer-link[aria-current] { color: var(--ws-blue, #005de7); background: var(--ws-active, #eaf2ff); }
.ds-explorer-link svg { flex: none; }
.ds-explorer-link:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }
@media (max-width: 900px) { .ds-explorer-link { min-height: 40px; font-size: 14px; } }
.ds-explorer-file { margin-left: 24px; padding-left: 21px; } .ds-explorer-folder { margin-left: 17px; gap: 11px; }

.ds-tabs { display: flex; align-items: end; height: 50px; padding-left: 15px; border-bottom: 1px solid var(--ws-rule, #e1e9f5); background: var(--ws-soft, #f5f8fd); }
.ds-tab { display: inline-flex; align-items: center; gap: 11px; min-height: 38px; max-width: calc(100% - 15px); padding: 8px 14px; border: 1px solid var(--ws-rule, #e1e9f5); border-bottom-color: var(--ws-panel, #ffffff); border-radius: 6px 6px 0 0; background: var(--ws-panel, #ffffff); color: var(--ws-ink, #0b1234); font-family: "Geist Mono", ui-monospace, monospace; font-size: 13px; font-weight: 600; transform: translateY(1px); }
.ds-tab { line-height: 1.5; }
.ds-tab > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-tab > svg { color: var(--ws-faint, #5a6d91); }
.ds-tab > svg:last-child { margin-left: 6px; }

.ds-project { font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; color: var(--ws-ink, #0b1234); background: var(--ws-panel, #ffffff); line-height: 1.5; }
.ds-project { display: grid; position: relative; grid-template-columns: 10% minmax(0, 1fr); min-height: calc(130 * var(--workspace-unit, 1px)); border: 1px solid var(--ws-rule, #e1e9f5); border-left: 4px solid var(--ws-green, #087c38); border-radius: 6px; }
.ds-project-index { display: flex; justify-content: center; padding-top: calc(12 * var(--workspace-unit, 1px)); border-right: 1px solid var(--ws-rule, #e1e9f5); color: var(--ws-green, #087c38); font-family: "Geist Mono", ui-monospace, monospace; font-size: clamp(17px, 1.395vw, 23px); font-weight: 550; }
.ds-project-body { display: flex; flex-direction: column; padding: calc(11 * var(--workspace-unit, 1px)) calc(17 * var(--workspace-unit, 1px)) calc(5 * var(--workspace-unit, 1px)); }
.ds-project-body h3 { font-size: clamp(18px, 1.594vw, 26px); font-weight: 700; line-height: 1.25; letter-spacing: -0.02em; }
.ds-project-body > p { margin-top: calc(3 * var(--workspace-unit, 1px)); color: var(--ws-muted, #536382); font-family: "Geist Mono", ui-monospace, monospace; font-size: clamp(13px, 1.063vw, 17px); line-height: 1.34; text-wrap: pretty; }
.ds-project-body h3, .ds-project-body > p { margin: 0; }
.ds-project-body > p { margin-top: calc(3 * var(--workspace-unit, 1px)); color: var(--ws-muted, #536382); font-family: "Geist Mono", ui-monospace, monospace; font-size: clamp(13px, 1.063vw, 17px); line-height: 1.34; text-wrap: pretty; }
.ds-project-footer { display: flex; align-items: center; gap: 15px; flex-wrap: wrap; min-height: calc(28 * var(--workspace-unit, 1px)); margin-top: auto; border-top: 1px solid var(--ws-rule, #e1e9f5); }
.ds-work-state { display: inline-flex; align-items: center; gap: 7px; color: var(--ws-green, #087c38); font-family: "Geist Mono", ui-monospace, monospace; font-size: 12px; }
.ds-work-state::before { width: 5px; height: 5px; border: 1px solid currentColor; border-radius: 50%; content: ""; }
@media (max-width: 900px) { .ds-project { grid-template-columns: 43px minmax(0, 1fr); min-height: 150px; } .ds-project-index { padding-top: 13px; font-size: 17px; } .ds-project-body { padding: 12px 13px 8px; } .ds-project-body h3 { font-size: 20px; line-height: 1.3; } .ds-project-body > p { margin-top: 8px; font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; font-size: 15px; line-height: 1.6; } .ds-project-footer { min-height: 31px; margin-top: 11px; padding-top: 5px; } .ds-work-state { font-size: 11px; } } @media (max-width: 540px) { .ds-project { grid-template-columns: 36px minmax(0, 1fr); } .ds-project-body { padding-inline: 11px; } .ds-project-body h3 { font-size: 19px; } }

.ds-focus { font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; color: var(--ws-ink, #0b1234); background: var(--ws-panel, #ffffff); line-height: 1.5; }
.ds-focus { display: grid; grid-template-columns: calc(44 * var(--workspace-unit, 1px)) minmax(0, 1fr); gap: 0; min-height: calc(128 * var(--workspace-unit, 1px)); padding: calc(7 * var(--workspace-unit, 1px)) calc(10 * var(--workspace-unit, 1px)); border: 1px solid var(--ws-rule, #e1e9f5); border-left: 3px solid var(--ws-green, #087c38); border-radius: 5px; }
.ds-focus-index { color: var(--ws-green, #087c38); font-family: "Geist Mono", ui-monospace, monospace; font-size: clamp(15px, 1.15vw, 18px); }
.ds-focus h3 { font-size: clamp(12px, 0.86vw, 13px); font-weight: 600; line-height: 1.34; letter-spacing: -0.025em; }
.ds-focus h3, .ds-focus p { margin: 0; }
.ds-focus p { margin-top: 6px; color: var(--ws-muted, #536382); font-size: clamp(12px, 0.9vw, 14px); line-height: 1.36; }
@media (max-width: 900px) { .ds-focus { grid-template-columns: 32px minmax(0, 1fr); gap: 4px; min-height: 0; padding: 12px 13px 15px; } .ds-focus-index { font-size: 16px; } .ds-focus h3 { font-size: 15px; line-height: 1.4; } .ds-focus p { margin-top: 9px; font-size: 14px; line-height: 1.65; } }

.ds-profile { position: relative; min-width: 0; border: 1px solid var(--ws-rule, #e1e9f5); border-radius: 5px; }
.ds-profile { background: var(--ws-bg, #fbfcff); color: var(--ws-ink, #0b1234); line-height: 1.5; }
.ds-panel-tab { display: flex; align-items: center; gap: 12px; min-height: 41px; padding: 8px 13px; border-bottom: 1px solid var(--ws-rule, #e1e9f5); background: var(--ws-soft, #f5f8fd); color: var(--ws-ink, #0b1234); font-family: "Geist Mono", ui-monospace, monospace; font-size: 13px; font-weight: 550; }
.ds-panel-tab { margin: 0; }
.ds-profile-body { position: relative; min-height: calc(373 * var(--workspace-unit, 1px)); padding: 10px 9px 18px 43px; font-family: "Geist Mono", ui-monospace, monospace; font-size: clamp(10px, 0.84vw, 13px); line-height: 1.7; counter-reset: json-line; }
.ds-profile-body::before { position: absolute; top: 0; bottom: 0; left: 32px; border-left: 1px solid var(--ws-rule, #e1e9f5); content: ""; }
.ds-profile-source { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; font: inherit; }
.ds-profile-source code { font: inherit; }
.ds-source-numbers { display: flex; position: absolute; top: 10px; left: 9px; flex-direction: column; width: 16px; color: var(--ws-faint, #5a6d91); font: inherit; text-align: right; pointer-events: none; user-select: none; }
.ds-source-numbers > span { height: 1lh; }
.ds-json-key { color: var(--ws-blue, #005de7); }
.ds-json-string, .ds-json-punctuation { color: var(--ws-green, #087c38); }
.ds-json-number { color: var(--ws-blue, #005de7); }
@media (max-width: 1199px) and (min-width: 901px) { .ds-profile-body { padding-left: 32px; padding-right: 7px; } .ds-profile-body::before { left: 24px; } .ds-profile-body .ds-source-numbers { left: 3px; width: 14px; } } @media (max-width: 900px) { .ds-profile-body { min-height: 0; font-size: 12px; padding-bottom: 20px; } }

.ds-notes { position: relative; min-width: 0; border: 1px solid var(--ws-rule, #e1e9f5); border-radius: 5px; }
.ds-notes { background: var(--ws-bg, #fbfcff); line-height: 1.5; }
.ds-notes-tab { display: flex; align-items: center; gap: 12px; min-height: 41px; padding: 8px 13px; border-bottom: 1px solid var(--ws-rule, #e1e9f5); background: var(--ws-soft, #f5f8fd); color: var(--ws-ink, #0b1234); font-family: "Geist Mono", ui-monospace, monospace; font-size: 13px; font-weight: 550; }
.ds-notes-tab { margin: 0; }
.ds-notes-copy { position: relative; padding: 12px 18px 18px 46px; color: var(--ws-muted, #536382); font-family: "Geist Mono", ui-monospace, monospace; font-size: clamp(11px, 0.92vw, 14px); line-height: 1.55; }
.ds-notes-copy::before { position: absolute; top: 0; bottom: 0; left: 32px; border-left: 1px solid var(--ws-rule, #e1e9f5); content: ""; }
.ds-source-numbers { display: flex; position: absolute; top: 10px; left: 9px; flex-direction: column; width: 16px; color: var(--ws-faint, #5a6d91); font: inherit; text-align: right; pointer-events: none; user-select: none; }
.ds-source-numbers > span { height: 1lh; }
.ds-notes-copy .ds-source-numbers { top: 12px; }
.ds-notes-source { display: flow-root; }
.ds-notes-source p { margin: 0; }
.ds-notes-source p + p { margin-top: 1lh; }
@media (max-width: 900px) { .ds-notes-copy { padding-left: 46px; font-size: 13px; } }

.ds-reader-contents, .ds-mobile-contents { font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; color: var(--ws-ink, #0b1234); line-height: 1.5; } .ds-reader-contents ol, .ds-mobile-contents ol { margin: 0; padding: 0; list-style: none; } .ds-contents-title { margin: 0; }
.ds-reader-contents { position: sticky; top: 28px; padding: 19px 16px 24px; }
.ds-contents-title { padding-bottom: 15px; color: var(--ws-ink, #0b1234); font-family: "Geist Mono", ui-monospace, monospace; font-size: 12px; font-weight: 600; }
.ds-reader-contents nav { border-top: 1px solid var(--ws-rule, #e1e9f5); }
.ds-reader-contents ol { padding-top: 12px !important; }
.ds-reader-contents li + li { margin-top: 2px; }
.ds-reader-contents li a { display: block; padding: 7px 0; color: var(--ws-muted, #536382); font-size: 13px; line-height: 1.65; text-decoration: none; }
.ds-reader-contents li a:hover { color: var(--ws-blue, #005de7); text-decoration: underline; }
.ds-contents-return { display: inline-flex; margin-top: 25px; padding-block: 8px; color: var(--ws-blue, #005de7); font-size: 12px; text-decoration: none; }
.ds-contents-return:hover { text-decoration: underline; }
.ds-mobile-contents { display: none; }
.ds-reader-contents a:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }
.ds-mobile-contents a:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }
.ds-mobile-contents summary:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }
@media (max-width: 900px) { .ds-reader-contents { display: none; } .ds-mobile-contents { display: block; margin-bottom: 26px; border-top: 1px solid var(--ws-rule, #e1e9f5); border-bottom: 1px solid var(--ws-rule, #e1e9f5); } .ds-mobile-contents > summary { display: flex; align-items: center; justify-content: space-between; gap: 15px; min-height: 46px; padding-block: 12px; color: var(--ws-ink, #0b1234); font-family: "Geist Mono", ui-monospace, monospace; font-size: 12px; cursor: pointer; list-style: none; } .ds-mobile-contents > summary::-webkit-details-marker { display: none; } .ds-mobile-contents[open] > summary svg { transform: rotate(180deg); } .ds-mobile-contents nav ol { padding-bottom: 14px; } .ds-mobile-contents li a { display: block; min-height: 40px; padding: 8px 0; color: var(--ws-blue, #005de7); font-size: 14px; line-height: 1.6; text-decoration: none; } .ds-mobile-contents li a:hover { text-decoration: underline; } }

.ds-reader { font-family: "Geist Sans", ui-sans-serif, system-ui, sans-serif; color: var(--ws-ink, #0b1234); line-height: 1.5; background: var(--ws-panel, #ffffff); } .ds-reader h1, .ds-reader p { margin: 0; }
.ds-reader { max-width: 72ch; padding-bottom: 64px; }
.ds-reader-header { padding-bottom: 32px; }
.ds-reader-back { display: inline-flex; min-height: 32px; margin-bottom: 18px; color: var(--ws-blue, #005de7); font-size: 13px; text-decoration: none; }
.ds-reader-back:hover { text-decoration: underline; }
.ds-reader h1 { font-size: 2.5rem; font-weight: 730; line-height: 1.16; letter-spacing: -0.035em; overflow-wrap: anywhere; }
.ds-reader .ds-reader-lead { margin-top: 22px; color: var(--ws-muted, #536382); font-size: 1.125rem; line-height: 1.75; }
.ds-reader-meta { display: flex; flex-wrap: wrap; gap: 5px 18px; margin-top: 20px; color: var(--ws-muted, #536382); font-family: "Geist Mono", ui-monospace, monospace; font-size: 11px; line-height: 1.7; }
.ds-reader-prose { max-width: 72ch; padding-top: 26px; border-top: 1px solid var(--ws-rule, #e1e9f5); font-size: 1.0625rem; line-height: 1.85; overflow-wrap: anywhere; }
.ds-reader-prose a { color: var(--ws-blue, #005de7); text-decoration: underline; text-decoration-thickness: 1px; }
.ds-reader-prose a:hover { text-decoration-thickness: 2px; }
.ds-reader a:focus-visible { outline: 2px solid var(--ws-blue, #005de7); outline-offset: 4px; }
@media (max-width: 1100px) and (min-width: 901px) { .ds-reader h1 { font-size: 2rem; } .ds-reader-prose { font-size: 1rem; } } @media (max-width: 900px) { .ds-reader { max-width: 72ch; margin-inline: auto; padding-bottom: 42px; } .ds-reader h1 { font-size: 2rem; } .ds-reader-header { padding-bottom: 26px; } .ds-reader .ds-reader-lead { margin-top: 18px; font-size: 1.0625rem; } .ds-reader-prose { padding-top: 24px; font-size: 1rem; line-height: 1.85; } } @media (max-width: 420px) { .ds-reader h1 { font-size: 1.75rem; } }
